(()=>{const A=Abibi;function render(){A.$('#cart-items').innerHTML=A.count()?A.state.cart.map(x=>{const p=A.product(x.id);return `<article class="cart-item"><img src="assets/image/${p.img}" alt="${p.name}"><div class="flex-grow-1"><h3>${p.name}</h3>${p.salePrice?`<small class="cart-saving">${A.fa(A.discount(p))}٪ تخفیف</small>`:''}<p>${x.extra?'پنیر اضافه':'سرو استاندارد'}${x.note?' · '+A.esc(x.note):''}</p><div class="qty"><button type="button" data-qty="1" data-key="${x.key}" aria-label="افزایش تعداد">+</button><span>${A.fa(x.qty)}</span><button type="button" data-qty="-1" data-key="${x.key}" aria-label="کاهش تعداد">−</button></div></div><div class="text-end">${A.money((A.unit(p)+x.extra)*x.qty)}<br><button class="btn btn-link btn-sm" data-remove="${x.key}" type="button">حذف</button></div></article>`}).join(''):A.empty('سبدت هنوز خالیه','از منو غذای موردعلاقه‌ات را انتخاب کن.');A.$('#cart-summary').innerHTML=A.summary();A.$('#checkout-link').classList.toggle('disabled',!A.count());A.$('#checkout-link').setAttribute('aria-disabled',String(!A.count()))}render();document.addEventListener('abibi:change',render)})();
